const input = $json || {};

const sampleContext = {
  version: '1.0',
  generatedAt: new Date().toISOString(),
  timezone: 'Asia/Dubai',
  request: { text: 'Bu hafta sonu sosyal etkinlik bul' },
  userContext: {
    identity: { name: 'Savaş', language: 'Turkish' },
    locations: { home: 'Palm Jumeirah, Dubai', work: 'Abu Dhabi' },
    goals: {
      social: 'Build a quality international social circle',
      dating: 'Create genuine dating opportunities',
      travel: 'Take more weekend trips'
    }
  },
  calendarContext: { today: [], tomorrow: [], thisWeek: [] },
  derivedContext: {
    isWeekend: true,
    calendarLoad: 'low',
    needsMoreSocial: true,
    needsMoreFitness: true,
    preferredPlanningWindow: { start: '17:00', end: '23:00' }
  },
  userState: {
    energyLevel: 'high',
    mood: 'social',
    budgetAED: 1200,
    maxTravelMinutes: 45
  }
};

const sampleDecision = {
  route: 'social_discovery',
  agentWorkflowName: 'Concierge OS - Social Discovery Agent',
  actionMode: 'discover_analyze_recommend',
  confidence: 0.94,
  isAmbiguous: false,
  needsDiscovery: true,
  requiresApproval: false,
  requiredContext: ['memory', 'calendar', 'derived_context'],
  reason: 'Social activity is below the weekly target.'
};

return [{
  json: {
    request: input.request || {
      text: 'Bu hafta sonu sosyal etkinlik bul',
      channel: 'manual_test',
      userId: 'savas',
      conversationId: 'manual-test',
      receivedAt: new Date().toISOString()
    },
    context: Object.keys(input.context || {}).length ? input.context : sampleContext,
    decision: Object.keys(input.decision || {}).length ? input.decision : sampleDecision,
    sourceEvents: Array.isArray(input.sourceEvents) ? input.sourceEvents : [],
    connectorOutputs: Array.isArray(input.connectorOutputs) ? input.connectorOutputs : [],
    forwardedItems: Array.isArray(input.forwardedItems) ? input.forwardedItems : [],
    metadata: {
      correlationId: input.metadata?.correlationId || `agent-orchestrator-${Date.now()}`,
      sourceWorkflow: input.metadata?.sourceWorkflow || 'Concierge OS - Agent Orchestrator',
      testMode: input.metadata?.testMode ?? true,
      ...input.metadata
    }
  }
}];

const input = $json || {};
const route = String(input.decision?.route || 'general_concierge').trim();

return [{
  json: {
    ...input,
    selectedRoute: route,
    isSocialDiscovery: route === 'social_discovery',
    targetWorkflow:
      route === 'social_discovery'
        ? 'Concierge OS - Social Discovery Agent'
        : input.decision?.agentWorkflowName || 'Concierge OS - General Concierge'
  }
}];

return [{
  json: {
    request: $json.request,
    context: $json.context,
    events: $json.sourceEvents || [],
    sourceEvents: $json.sourceEvents || [],
    connectorOutputs: $json.connectorOutputs || [],
    forwardedItems: $json.forwardedItems || [],
    metadata: {
      ...$json.metadata,
      selectedRoute: $json.selectedRoute,
      sourceWorkflow: 'Concierge OS - Agent Orchestrator'
    }
  }
}];

const socialOutput = $json || {};
const original = $('Prepare Social Agent Input').item.json || {};

return [{
  json: {
    request: original.request,
    context: original.context,
    recommendations: socialOutput.result?.recommendations || [],
    agentResponses: [socialOutput],
    metadata: {
      ...original.metadata,
      sourceWorkflow: 'Concierge OS - Agent Orchestrator',
      previousWorkflow: 'Concierge OS - Social Discovery Agent'
    }
  }
}];

const recommendationOutput = $json || {};
const original = $('Prepare Recommendation Input').item.json || {};

return [{
  json: {
    request: original.request,
    context: original.context,
    recommendationEngineOutput: recommendationOutput,
    metadata: {
      ...original.metadata,
      sourceWorkflow: 'Concierge OS - Agent Orchestrator',
      previousWorkflow: 'Concierge OS - Recommendation Engine'
    }
  }
}];

const lifeImpactOutput = $json || {};
const original = $('Prepare Life Impact Input').item.json || {};

return [{
  json: {
    request: original.request,
    context: original.context,
    lifeImpactOutput,
    metadata: {
      ...original.metadata,
      sourceWorkflow: 'Concierge OS - Agent Orchestrator',
      previousWorkflow: 'Concierge OS - Life Impact Scoring Engine'
    }
  }
}];

return [{
  json: {
    success: true,
    result: {
      selectedAgent: $json.selectedRoute || 'general_concierge',
      selectedRoute: $json.selectedRoute || 'general_concierge',
      targetWorkflow: $json.targetWorkflow || null,
      executionStatus: 'agent_not_implemented',
      recommendations: []
    },
    memoryUpdates: [],
    approvalRequests: [],
    logs: [{
      timestamp: new Date().toISOString(),
      workflow: 'Concierge OS - Agent Orchestrator',
      level: 'warning',
      correlationId: $json.metadata?.correlationId || '',
      message: 'Selected agent is not implemented.',
      details: {
        route: $json.selectedRoute,
        targetWorkflow: $json.targetWorkflow
      }
    }],
    nextAction: {
      type: 'implement_or_connect_agent',
      targetWorkflow: $json.targetWorkflow || null
    },
    error: null
  }
}];
